/**
 * Builds the `<artifacts>` system prompt block listing available artifacts.
 */
function buildArtifactListing(artifacts: Artifact[]): string {
  if (artifacts.length === 0) {
    return (
      `<artifacts>\n` +
      `No artifacts are currently available in the session.\n` +
      `</artifacts>`
    );
  }

